# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Interior kernel: branch-free, all 27 taps guaranteed in-bounds
// Handles output voxels od in [2, Dout-3], oh in [2, Hout-3], ow in [2, Wout-3]
__global__ void conv_transpose3d_interior_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int od_start, int oh_start, int ow_start,
    int od_end, int oh_end, int ow_end
) {
    // Grid: blockIdx.z = n*Cout + co, blockIdx.y = od_interior, blockIdx.x = oh_interior*Wint + ow_interior
    int Dint = od_end - od_start;
    int Hint = oh_end - oh_start;
    int Wint = ow_end - ow_start;

    int nc_idx = blockIdx.z;
    int n  = nc_idx / Cout;
    int co = nc_idx % Cout;

    int od_rel = blockIdx.y;
    int hw_rel = blockIdx.x * blockDim.x + threadIdx.x;
    if (hw_rel >= Hint * Wint) return;

    int oh_rel = hw_rel / Wint;
    int ow_rel = hw_rel % Wint;

    int od = od_rel + od_start;
    int oh = oh_rel + oh_start;
    int ow = ow_rel + ow_start;

    float acc = 0.0f;

    // For stride=1, padding=0: id = od - kd, ih = oh - kh, iw = ow - kw
    // Interior guarantees: id in [0, Din-1], ih in [0, Hin-1], iw in [0, Win-1] for all k in {0,1,2}
    for (int ci = 0; ci < Cin; ++ci) {
        const float* inp_base = input + (n * Cin + ci) * (Din * Hin * Win);
        const float* w_base   = weight + (ci * Cout + co) * 27;

        #pragma unroll
        for (int kd = 0; kd < 3; ++kd) {
            int id = od - kd;
            #pragma unroll
            for (int kh = 0; kh < 3; ++kh) {
                int ih = oh - kh;
                #pragma unroll
                for (int kw = 0; kw < 3; ++kw) {
                    int iw = ow - kw;
                    acc += inp_base[(id * Hin + ih) * Win + iw] * w_base[kd * 9 + kh * 3 + kw];
                }
            }
        }
    }

    output[((n * Cout + co) * Dout + od) * Hout * Wout + oh * Wout + ow] = acc;
}

// Boundary kernel: handles all output voxels NOT in the interior
__global__ void conv_transpose3d_boundary_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int od_start, int oh_start, int ow_start,
    int od_end, int oh_end, int ow_end
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * Cout * Dout * Hout * Wout;
    if (idx >= total) return;

    int ow = idx % Wout; int tmp = idx / Wout;
    int oh = tmp % Hout; tmp /= Hout;
    int od = tmp % Dout; tmp /= Dout;
    int co = tmp % Cout;
    int n  = tmp / Cout;

    // Skip interior voxels (handled by interior kernel)
    if (od >= od_start && od < od_end &&
        oh >= oh_start && oh < oh_end &&
        ow >= ow_start && ow < ow_end) return;

    float acc = 0.0f;

    for (int ci = 0; ci < Cin; ++ci) {
        const float* inp_base = input + (n * Cin + ci) * (Din * Hin * Win);
        const float* w_base   = weight + (ci * Cout + co) * 27;

        #pragma unroll
        for (int kd = 0; kd < 3; ++kd) {
            int id = od - kd;
            if (id < 0 || id >= Din) continue;
            #pragma unroll
            for (int kh = 0; kh < 3; ++kh) {
                int ih = oh - kh;
                if (ih < 0 || ih >= Hin) continue;
                #pragma unroll
                for (int kw = 0; kw < 3; ++kw) {
                    int iw = ow - kw;
                    if (iw < 0 || iw >= Win) continue;
                    acc += inp_base[(id * Hin + ih) * Win + iw] * w_base[kd * 9 + kh * 3 + kw];
                }
            }
        }
    }

    output[((n * Cout + co) * Dout + od) * Hout * Wout + oh * Wout + ow] = acc;
}

torch::Tensor conv_transpose3d_k3s1p0_split_cuda(torch::Tensor x, torch::Tensor weight) {
    int N    = x.size(0);
    int Cin  = x.size(1);
    int Din  = x.size(2);
    int Hin  = x.size(3);
    int Win  = x.size(4);
    int Cout = weight.size(1);
    int Dout = Din + 2;
    int Hout = Hin + 2;
    int Wout = Win + 2;

    auto output = torch::zeros({N, Cout, Dout, Hout, Wout}, x.options());

    // Interior bounds: od in [2, Dout-3), oh in [2, Hout-3), ow in [2, Wout-3)
    // i.e. od in [2, Din], oh in [2, Hin], ow in [2, Win]
    int od_start = 2, od_end = Dout - 1;  // exclusive end = Din+1
    int oh_start = 2, oh_end = Hout - 1;
    int ow_start = 2, ow_end = Wout - 1;

    int Dint = od_end - od_start;
    int Hint = oh_end - oh_start;
    int Wint = ow_end - ow_start;

    if (Dint > 0 && Hint > 0 && Wint > 0) {
        int threads = 128;
        int hw_blocks = (Hint * Wint + threads - 1) / threads;
        dim3 grid_int(hw_blocks, Dint, N * Cout);
        conv_transpose3d_interior_kernel<<<grid_int, threads>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            N, Cin, Cout,
            Din, Hin, Win,
            Dout, Hout, Wout,
            od_start, oh_start, ow_start,
            od_end, oh_end, ow_end
        );
    }

    // Boundary kernel
    int total = N * Cout * Dout * Hout * Wout;
    int threads_b = 256;
    int blocks_b = (total + threads_b - 1) / threads_b;
    conv_transpose3d_boundary_kernel<<<blocks_b, threads_b>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, Cout,
        Din, Hin, Win,
        Dout, Hout, Wout,
        od_start, oh_start, ow_start,
        od_end, oh_end, ow_end
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a transposed 3D convolution with square input and square kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the square convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            output_padding (int, optional): Additional size added to one side of the output shape. Defaults to 0.
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
