        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        conv = self.conv_transpose3d
        if (
        x.is_cuda and
        x.dtype == torch.float32 and
        x.dim() == 5 and
        x.is_contiguous() and
        conv.weight.is_cuda and
        conv.weight.dtype == torch.float32 and
        conv.weight.is_contiguous() and
        conv.bias is None and
        conv.groups == 1 and
        conv.kernel_size == (3, 3, 3) and
        conv.stride == (1, 1, 1) and
        conv.padding == (0, 0, 0) and
        conv.output_padding == (0, 0, 0)
        ):
            return _stark_get_extension().conv_transpose3d_k3s1p0_split_cuda(x, conv.weight)
